import { escapeHTML as esc, formatNumber as fmt } from './ui-utils.mjs';

(() => {
  const app = document.querySelector('#app');
  const toastRegion = document.querySelector('#toast-region');
  let state = { user: null, servers: [], runes: [], selected: null, route: 'servers', stats: null, socket: null, filePath: '', fileRows: [], users: [] };
  const icon = (name) => ({ grid:'▦', server:'◉', rune:'▤', storage:'▥', user:'♙', log:'⌘', notify:'◈', folder:'▱', plus:'+', close:'×', settings:'⚙', moon:'◐', sun:'☼', arrow:'↗', play:'▶', stop:'■', rotate:'↻', trash:'⌫', download:'↓', upload:'↑', refresh:'⟳', shield:'◇', check:'✓', warn:'!' }[name] || '•');
  const api = async (path, options = {}) => {
    const headers = new Headers(options.headers || {});
    if (options.body && !(options.body instanceof FormData)) headers.set('Content-Type', 'application/json');
    const res = await fetch(path, { credentials:'same-origin', ...options, headers });
    const type = res.headers.get('content-type') || '';
    const body = type.includes('application/json') ? await res.json() : await res.text();
    if (!res.ok) throw new Error(body?.error || body || `Request failed (${res.status})`);
    return body;
  };
  const toast = (message, kind = 'info') => {
    const el = document.createElement('div'); el.className = `toast ${kind}`; el.textContent = message; toastRegion.append(el);
    setTimeout(() => { el.classList.add('leaving'); setTimeout(() => el.remove(), 250); }, 4200);
  };
  const statusInfo = (status) => ({running:['Running','good'],starting:['Starting','warn'],installing:['Installing','warn'],error:['Needs attention','bad'],stopped:['Stopped','muted'],created:['Not installed','muted']}[status] || [status || 'Unknown','muted']);

  async function boot() {
    try { state.user = await api('/api/me'); await refresh(); render(); }
    catch { renderLogin(); }
  }
  async function refresh() {
    const [servers, runes] = await Promise.all([api('/api/servers'), api('/api/gameskills')]);
    state.servers = servers; state.runes = runes;
    if (state.selected) state.selected = servers.find(s => s.id === state.selected.id) || null;
  }
  function renderLogin() {
    state.user = null;
    app.innerHTML = `<main class="login-wrap"><section class="login-brand"><div class="brand-lockup"><img class="brand-logo big" src="/brand.svg" alt=""><span>Docklight</span></div><div class="login-copy"><div class="eyebrow">YOUR SERVERS, UNDER ONE ROOF</div><h1>Everything running.<br><em>Nothing in the way.</em></h1><p>One panel for the games you play and the services you rely on.</p></div><div class="login-foot"><span class="dot green"></span> Self-hosted · Local data · No telemetry</div></section><section class="login-card-wrap"><form id="login-form" class="login-card"><div class="eyebrow">WELCOME BACK</div><h2>Sign in</h2><p class="muted-copy">Use your panel account to continue.</p><label>Username<input name="username" autocomplete="username" required autofocus></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><label id="totp-row" class="hidden">Authenticator code<input name="totp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" placeholder="6-digit code"></label><button class="button primary wide" type="submit">Sign in <span>→</span></button><div id="login-error" class="form-error" role="alert"></div><div class="login-note">Your panel is private to this machine.</div></form></section></main>`;
    document.querySelector('#login-form').addEventListener('submit', async (e) => {
      e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); const error = document.querySelector('#login-error'); error.textContent = '';
      try { const out = await api('/api/login', {method:'POST',body:JSON.stringify(data)}); state.user = out.user; await refresh(); render(); }
      catch (err) { error.textContent = err.message; if (/authenticator|six-digit|code/i.test(err.message)) { document.querySelector('#totp-row').classList.remove('hidden'); document.querySelector('[name="totp"]').focus(); } }
    });
  }
  function render() {
    if (!state.user) return renderLogin();
    const active = state.selected;
    app.innerHTML = `<div class="layout"><aside class="sidebar"><a href="#" class="brand-lockup" data-action="home"><img class="brand-logo" src="/brand.svg" alt=""><span>Docklight</span></a><div class="side-label">PANEL</div><button class="nav-item ${!active&&state.route==='servers'?'active':''}" data-action="home"><span>${icon('grid')}</span><span>Servers</span><b>${state.servers.length}</b></button><button class="nav-item ${!active&&state.route==='runes'?'active':''}" data-action="runes"><span>${icon('rune')}</span><span>Templates</span></button>${state.user.role==='admin'?`<div class="side-label side-spacer">MANAGE</div><button class="nav-item ${!active&&state.route==='storage'?'active':''}" data-action="storage"><span>${icon('storage')}</span><span>Backup storage</span></button><button class="nav-item ${state.route==='users'?'active':''}" data-action="users"><span>${icon('user')}</span><span>Users & access</span></button><button class="nav-item ${state.route==='audit'?'active':''}" data-action="audit"><span>${icon('log')}</span><span>Audit history</span></button><button class="nav-item ${state.route==='notifications'?'active':''}" data-action="notifications"><span>${icon('notify')}</span><span>Notifications</span></button>`:''}<div class="sidebar-bottom"><div class="instance-card"><span class="dot green"></span><span><b>Panel online</b><small>Single host</small></span><span class="instance-menu">···</span></div><button class="profile" data-action="profile"><span class="avatar">${esc(state.user.username[0]?.toUpperCase())}</span><span><b>${esc(state.user.username)}</b><small>${state.user.role==='admin'?'Administrator':'Panel user'}</small></span><span class="more">⌄</span></button></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><span>Panel</span><span class="crumb-sep">/</span><b>${active?esc(active.name):esc(state.route==='users'?'Users & access':state.route==='audit'?'Audit history':state.route==='notifications'?'Notifications':state.route==='storage'?'Backup storage':state.route==='runes'?'Templates':'Servers')}</b></div><div class="top-actions"><button class="icon-button theme-toggle" title="Toggle light or dark theme" data-action="theme">${icon('moon')}</button><span class="top-divider"></span><button class="user-chip" data-action="profile"><span class="avatar small">${esc(state.user.username[0]?.toUpperCase())}</span><span>${esc(state.user.username)}</span><span class="chevron">⌄</span></button></div></header><div class="content" id="view"></div></main></div>`;
    if (active) renderDetail(active); else if (state.route==='users') renderUsers(); else if (state.route==='audit') renderAudit(); else if (state.route==='notifications') renderNotifications(); else if (state.route==='storage'&&state.user.role==='admin') renderBackupStorage(); else if (state.route==='runes') renderRunes(); else renderServers();
    bindShell();
  }
  function bindShell() {
    document.querySelectorAll('[data-action]').forEach(el => el.addEventListener('click', async (e) => { e.preventDefault(); const action=el.dataset.action;
      if(action==='home'){state.selected=null;state.route='servers';await refresh();render();}
      if(action==='runes'){state.selected=null;state.route='runes';render();}
      if(action==='users'){state.selected=null;state.route='users';render();}
      if(action==='audit'){state.selected=null;state.route='audit';render();}
      if(action==='notifications'){state.selected=null;state.route='notifications';render();}
      if(action==='storage'&&state.user.role==='admin'){state.selected=null;state.route='storage';render();}
      if(action==='profile') showProfile();
      if(action==='theme'){document.documentElement.classList.toggle('light');localStorage.setItem('ygg-theme',document.documentElement.classList.contains('light')?'light':'dark');}
    }));
  }
  function renderServers() {
    const view=document.querySelector('#view'); const running=state.servers.filter(s=>s.status==='running').length; const starting=state.servers.filter(s=>['starting','installing'].includes(s.status)).length;
    view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">YOUR INFRASTRUCTURE</div><h1>Servers</h1><p>Manage the games and apps running on this host.</p></div><button class="button primary" data-action="new-server"><span class="plus">+</span> New server</button></div><div class="metric-row"><div class="metric-card"><span class="metric-icon pale-green">◉</span><div><div class="metric-label">TOTAL SERVERS</div><b>${state.servers.length}</b></div><span class="metric-caption">in this panel</span></div><div class="metric-card"><span class="metric-icon pale-blue">↗</span><div><div class="metric-label">RUNNING</div><b>${running}</b></div><span class="metric-caption">${starting?`${starting} starting`: 'healthy services'}</span></div><div class="metric-card"><span class="metric-icon pale-gold">◷</span><div><div class="metric-label">AVAILABLE TEMPLATES</div><b>${state.runes.length}</b></div><span class="metric-caption">ready to deploy</span></div></div><div class="section-head"><div><h2>All servers <span class="count-pill">${state.servers.length}</span></h2><p>Services on this machine</p></div><button class="button subtle" data-action="refresh">${icon('refresh')} Refresh</button></div>${state.servers.length?`<div class="server-grid">${state.servers.map(serverCard).join('')}</div>`:`<section class="empty-state"><div class="empty-illustration"><span>▤</span><i></i><i></i><i></i></div><h2>Your server list is clear</h2><p>Choose a template to bring a game or app online.</p><button class="button primary" data-action="new-server">Create your first server <span>→</span></button></section>`}`;
    if(state.user.role!=='admin'&&state.runes.length===0){view.querySelectorAll('[data-action="new-server"]').forEach(el=>el.remove());const empty=view.querySelector('.empty-state');if(empty)empty.innerHTML='<h2>No accessible servers</h2><p>Ask an administrator to grant you server access.</p>';}
    view.querySelectorAll('[data-server-op]').forEach(el=>{const server=state.servers.find(s=>s.id===el.dataset.server);if(!server?.permissions?.includes('server.control'))el.remove();});
    view.querySelector('[data-action="new-server"]')?.addEventListener('click',()=>newServerModal());view.querySelector('[data-action="refresh"]')?.addEventListener('click',async()=>{await refresh();render();});
    view.querySelectorAll('.server-card[data-server]').forEach(el=>el.addEventListener('click',()=>{state.selected=state.servers.find(s=>s.id===el.dataset.server);render();}));
    view.querySelectorAll('[data-server-op]').forEach(el=>el.addEventListener('click',async e=>{e.stopPropagation();await serverAction(el.dataset.server,el.dataset.serverOp);}));
  }
  function serverCard(s){const [label,kind]=statusInfo(s.status);const rune=state.runes.find(x=>x.id===s.gameskill_id);const port=s.ports?.web||s.ports?.game;return `<article class="server-card" data-server="${esc(s.id)}"><div class="card-top"><div class="server-glyph ${s.gameskill_id.includes('minecraft')?'glyph-game':'glyph-app'}">${s.gameskill_id.includes('minecraft')?'✦':'◇'}</div><div class="card-title"><h3>${esc(s.name)}</h3><span>${esc(rune?.name||s.gameskill_id)}</span></div><span class="status-badge ${kind}"><i></i>${label}</span></div><div class="card-body"><div class="card-meta"><span>${s.installed?'Installed':'Setup required'}</span><span class="meta-sep">·</span><span>${port?`Port ${fmt(port)}`:'No public port'}</span></div><div class="card-progress"><i class="${kind}"></i></div></div><div class="card-footer"><span class="card-id">${esc(s.id.slice(0,8))}</span><div class="quick-actions">${s.status==='running'?`<button title="Stop" data-server-op="stop" data-server="${esc(s.id)}">■</button><button title="Restart" data-server-op="restart" data-server="${esc(s.id)}">↻</button>`:`<button title="${s.installed?'Start':'Install'}" data-server-op="${s.installed?'start':'install'}" data-server="${esc(s.id)}">▶</button>`}<button title="Open server" data-server="${esc(s.id)}">↗</button></div></div></article>`;}
  async function serverAction(id,op){try{const result=await api(`/api/servers/${id}/${op}`,{method:'POST',body:'{}'});toast(op==='install'?'Installation started':`${op[0].toUpperCase()+op.slice(1)} requested`,'success');await refresh();state.selected=state.servers.find(s=>s.id===id);render();if(op==='install')watchInstall(id);}catch(e){toast(e.message,'error');}}
  function watchInstall(id){const timer=setInterval(async()=>{try{const x=await api(`/api/servers/${id}/install/status`);if(x.done||x.installed){clearInterval(timer);await refresh();if(state.selected?.id===id)render();toast(x.error||'Installation finished','success');}else if(x.status==='error'){clearInterval(timer);toast(x.error||'Installation failed','error');}}catch{clearInterval(timer);}},2500);}

  function renderDetail(s){const v=document.querySelector('#view');const [label,kind]=statusInfo(s.status);const rune=state.runes.find(x=>x.id===s.gameskill_id);v.innerHTML=`<div class="detail-heading"><div class="detail-title"><button class="back-button" data-action="home">←</button><div class="server-glyph large ${s.gameskill_id.includes('minecraft')?'glyph-game':'glyph-app'}">${s.gameskill_id.includes('minecraft')?'✦':'◇'}</div><div><div class="title-line"><h1>${esc(s.name)}</h1><span class="status-badge ${kind}"><i></i>${label}</span></div><p>${esc(rune?.name||s.gameskill_id)} <span class="meta-sep">·</span> created ${esc(s.created_at)}</p></div></div><div class="detail-actions">${s.status==='running'?`<button class="button subtle" data-op="stop">■ Stop</button><button class="button primary" data-op="restart">↻ Restart</button>`:`<button class="button primary" data-op="${s.installed?'start':'install'}">▶ ${s.installed?'Start':'Install'}</button>`}<button class="icon-button danger-icon" data-op="delete" title="Delete server">⌫</button></div></div><nav class="tabs"><button class="tab active" data-tab="overview">Overview</button><button class="tab" data-tab="console">Console</button><button class="tab" data-tab="files">Files</button><button class="tab" data-tab="backups">Backups</button><button class="tab" data-tab="schedules">Schedules</button><button class="tab" data-tab="history">History</button><button class="tab" data-tab="settings">Settings</button></nav><div id="detail-body"></div>`;
    if(s.error_message){const banner=document.createElement('div');banner.className='error-banner';banner.textContent=s.error_message;v.querySelector('.tabs').before(banner);}
    const permissions=new Set(s.permissions||[]);
    if(!permissions.has('server.control'))v.querySelectorAll('[data-op="start"],[data-op="install"],[data-op="stop"],[data-op="restart"],[data-tab="settings"]').forEach(el=>el.remove());
    if(!permissions.has('server.delete'))v.querySelector('[data-op="delete"]')?.remove();
    if(!permissions.has('server.console'))v.querySelector('[data-tab="console"]')?.remove();
    if(!permissions.has('server.files'))v.querySelector('[data-tab="files"]')?.remove();if(!permissions.has('server.backup'))v.querySelector('[data-tab="backups"]')?.remove();if(!permissions.has('server.schedule'))v.querySelector('[data-tab="schedules"]')?.remove();
    v.querySelector('[data-action="home"]').addEventListener('click',()=>{state.selected=null;render();});v.querySelectorAll('[data-op]').forEach(b=>b.addEventListener('click',async()=>{if(b.dataset.op==='delete'){if(!confirm(`Delete ${s.name}, its server data, and all local and remote backup copies? This cannot be undone.`))return;try{await api(`/api/servers/${s.id}`,{method:'DELETE'});state.selected=null;await refresh();render();toast('Server and data deleted','success')}catch(e){toast(e.message,'error')}return;}await serverAction(s.id,b.dataset.op);}));v.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{v.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(state.socket){state.socket.close();state.socket=null;}if(b.dataset.tab==='overview')renderOverview(s);if(b.dataset.tab==='console')renderConsole(s);if(b.dataset.tab==='files')renderFiles(s);if(b.dataset.tab==='backups')renderBackups(s);if(b.dataset.tab==='schedules')renderSchedules(s);if(b.dataset.tab==='history')renderCrashHistory(s);if(b.dataset.tab==='settings')renderSettings(s);}));renderOverview(s);}
  async function renderBackups(s){
    const b=document.querySelector('#detail-body');
    let remoteEnabled=false;
    try{remoteEnabled=(await api('/api/backups/target/status')).enabled===true}catch{}
    const admin=state.user.role==='admin';
    b.innerHTML=`<section class="panel-card backup-panel"><div class="panel-head"><div><div class="eyebrow">RECOVERY POINTS</div><h2>Backups</h2><p>Encrypted, verified snapshots of this server's data.</p></div><div class="backup-actions">${admin?'<button class="button subtle" id="manage-backup-storage">Storage settings</button>':''}<button class="button subtle" id="prune-backups">Prune to retention</button><button class="button primary" id="create-backup">Create backup</button></div></div><div class="backup-create-row"><label class="backup-destination">Save a copy to<select id="backup-destination"><option value="local">Panel storage</option><option value="s3" ${remoteEnabled?'':'disabled'}>S3-compatible bucket${remoteEnabled?'':' · not configured'}</option></select></label><span class="backup-destination-hint">${remoteEnabled?'S3 uploads stream directly from the archive and are verified after upload.':'Local backups use the panel backup path.'}</span></div><div class="backup-note">Stop the server before creating or restoring a backup. Archives are encrypted with this panel's <code>auth.secret_key</code>; keep that key with the database.</div><div class="backup-list" id="backup-list"><div class="files-empty">Loading backups…</div></div></section>`;
    const host=document.querySelector('#backup-list');
    const create=document.querySelector('#create-backup');
    const prune=document.querySelector('#prune-backups');
    const destination=document.querySelector('#backup-destination');
    if(['running','starting','installing'].includes(s.status))create.disabled=true;
    document.querySelector('#manage-backup-storage')?.addEventListener('click',()=>{state.selected=null;state.route='storage';render()});
    create.onclick=async()=>{create.disabled=true;try{const result=await api(`/api/servers/${s.id}/backups`,{method:'POST',body:JSON.stringify({destination:destination.value})});await load();toast(result.warning||'Backup created and passed integrity verification','success')}catch(e){toast(e.message,'error')}finally{create.disabled=['running','starting','installing'].includes(s.status)}};
    prune.onclick=async()=>{prune.disabled=true;try{const result=await api(`/api/servers/${s.id}/backups/prune`,{method:'POST',body:'{}'});await load();toast(`Removed ${result.removed} old backup${result.removed===1?'':'s'}`,'success')}catch(e){toast(e.message,'error')}finally{prune.disabled=false}};
    async function load(){try{const items=await api(`/api/servers/${s.id}/backups`);if(!items.length){host.innerHTML='<div class="files-empty">No backups yet. Create one while the server is stopped.</div>';return}host.innerHTML=items.map(item=>{const rawTime=item.created_at;const time=new Date(rawTime.includes('T')?rawTime:`${rawTime.replace(' ','T')}Z`);const date=Number.isNaN(time.getTime())?esc(item.created_at):esc(time.toLocaleString());const storage=item.storage==='s3'?'S3 compatible':'Panel storage';return `<article class="backup-row"><div class="backup-summary"><b>${date}<span class="backup-storage-tag ${item.storage==='s3'?'remote':''}">${storage}</span></b><small>${formatBytes(item.size_bytes)} archive · ${formatBytes(item.data_bytes)} data · ${item.files} files · ${item.directories} folders</small></div><div class="backup-row-actions"><button class="button subtle" data-backup-op="verify" data-backup="${esc(item.id)}">Verify</button><button class="button subtle" data-backup-op="restore" data-backup="${esc(item.id)}" ${['running','starting','installing'].includes(s.status)?'disabled':''}>Restore</button><button class="button danger" data-backup-op="delete" data-backup="${esc(item.id)}">Delete</button></div></article>`}).join('');host.querySelectorAll('[data-backup-op]').forEach(button=>button.onclick=async()=>{const id=button.dataset.backup,op=button.dataset.backupOp;if(op==='restore'&&!confirm('Restore this backup? Current server data will be replaced.'))return;if(op==='delete'&&!confirm('Delete this backup permanently?'))return;button.disabled=true;try{if(op==='verify'){const x=await api(`/api/servers/${s.id}/backups/${id}/verify`,{method:'POST',body:'{}'});toast(`Backup verified · ${x.files} files · ${formatBytes(x.bytes)}`,'success')}if(op==='restore'){const x=await api(`/api/servers/${s.id}/backups/${id}/restore`,{method:'POST',body:'{}'});await refresh();state.selected=state.servers.find(server=>server.id===s.id)||s;render();toast(x.warning||'Server data restored from backup','success');return}if(op==='delete'){await api(`/api/servers/${s.id}/backups/${id}`,{method:'DELETE'});toast('Backup deleted','success')}await load()}catch(e){toast(e.message,'error')}finally{button.disabled=false}})}catch(e){host.innerHTML=`<div class="files-empty error-text">${esc(e.message)}</div>`}}
    await load();
  }

  async function renderBackupStorage(){
    const view=document.querySelector('#view');
    view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">STORAGE & RECOVERY</div><h1>Backup storage</h1><p>Choose where server snapshots live and verify access before the first upload.</p></div></div><div class="storage-grid"><section class="panel-card storage-card" id="s3-storage-card"><div class="files-empty">Loading destination settings…</div></section><aside class="panel-card storage-help"><span class="storage-mark">${icon('storage')}</span><div class="eyebrow">S3 COMPATIBLE</div><h2>Your bucket, your keys.</h2><p>Connect Amazon S3 or a compatible service such as MinIO. Docklight signs requests directly and keeps its access credentials encrypted in the panel database.</p><ul><li>Create the bucket before connecting it.</li><li>Use HTTPS except for a local loopback test endpoint.</li><li>Allow object upload, download, and delete for the configured prefix.</li></ul><p class="muted-copy">Backups are retained from Docklight's database records. Removing a backup through the panel also removes its object.</p></aside></div>`;
    const card=view.querySelector('#s3-storage-card');
    try{
      const target=await api('/api/backups/target');
      const stateLabel=target.enabled&&target.configured?'Ready for new backups':target.configured?'Configured · disabled':'Not configured';
      card.innerHTML=`<div class="storage-card-head"><div><div class="eyebrow">REMOTE DESTINATION</div><h2>S3-compatible storage</h2></div><span class="status-badge ${target.enabled&&target.configured?'good':'muted'}"><i></i>${stateLabel}</span></div><div class="storage-facts"><div><small>ENDPOINT</small><b>${target.endpoint?esc(target.endpoint):'Not set'}</b></div><div><small>BUCKET</small><b>${target.bucket?esc(target.bucket):'Not set'}</b></div><div><small>REGION</small><b>${target.region?esc(target.region):'Not set'}</b></div><div><small>KEYS</small><b>${target.access_key_configured&&target.secret_key_configured?'Encrypted and saved':'Not set'}</b></div><div><small>OBJECT PREFIX</small><b>${target.prefix?esc(target.prefix):'docklight/'}</b></div></div><p class="muted-copy">Existing S3 backups lock the endpoint, bucket, region and prefix until those backup records are removed. Credentials can still be rotated.</p><div class="storage-actions"><button class="button primary" id="edit-s3-target">${target.configured?'Edit destination':'Connect a bucket'}</button>${target.configured?'<button class="button subtle" id="test-s3-target">Test connection</button>':''}${target.configured?'<button class="button danger" id="clear-s3-target">Clear destination</button>':''}</div><div id="storage-feedback" class="form-error" role="alert"></div>`;
      card.querySelector('#edit-s3-target').onclick=()=>showBackupTargetEditor(target);
      card.querySelector('#test-s3-target')?.addEventListener('click',async event=>{const button=event.currentTarget,feedback=card.querySelector('#storage-feedback');button.disabled=true;feedback.textContent='';try{await api('/api/backups/target/test',{method:'POST',body:'{}'});toast('Bucket accepted an upload and delete','success')}catch(err){feedback.textContent=err.message}finally{button.disabled=false}});
      card.querySelector('#clear-s3-target')?.addEventListener('click',async event=>{if(!confirm('Clear the saved S3 destination? Existing S3 backup records must be deleted first.'))return;const button=event.currentTarget,feedback=card.querySelector('#storage-feedback');button.disabled=true;feedback.textContent='';try{await api('/api/backups/target',{method:'PUT',body:JSON.stringify({clear_target:true})});toast('S3 destination cleared','success');await renderBackupStorage()}catch(err){feedback.textContent=err.message;button.disabled=false}});
    }catch(err){card.innerHTML=`<p class="error-text">${esc(err.message)}</p>`}
  }

  function showBackupTargetEditor(target){
    modal(`<div class="modal-heading"><div><div class="eyebrow">BACKUP DESTINATION</div><h2>S3-compatible bucket</h2></div><button class="icon-button" data-close>×</button></div><form id="s3-target-form" class="user-manage backup-target-form"><label>Endpoint<input name="endpoint" type="url" required value="${esc(target.endpoint||'')}" placeholder="https://s3.example.com"><small>Use the service endpoint. Docklight uses path-style bucket requests.</small></label><div class="two-fields"><label>Bucket<input name="bucket" required value="${esc(target.bucket||'')}" placeholder="my-game-backups"></label><label>Region<input name="region" required value="${esc(target.region||'')}" placeholder="us-east-1"></label></div><label>Object prefix<input name="prefix" value="${esc(target.prefix||'')}" placeholder="production"><small>Leave empty to use Docklight's default object prefix.</small></label><label>Access key<input name="access_key" autocomplete="off" placeholder="${target.access_key_configured?'Saved securely · leave blank to keep current':'Access key ID'}"></label><label>Secret key<input name="secret_key" type="password" autocomplete="new-password" placeholder="${target.secret_key_configured?'Saved securely · leave blank to keep current':'Secret access key'}"></label><label class="checkline"><input type="checkbox" name="enabled" ${target.enabled?'checked':''}> Offer this destination when creating backups</label><div class="backup-target-hint">Docklight encrypts saved credentials with <code>auth.secret_key</code>. Keep that key with the panel database to retain access to existing backups.</div><div id="s3-target-error" class="form-error" role="alert"></div><div class="modal-actions"><button class="button subtle" type="button" data-close>Cancel</button><button class="button subtle" type="button" id="save-test-s3">Save & test</button><button class="button primary" type="submit">Save destination</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);
    const form=document.querySelector('#s3-target-form'),error=form.querySelector('#s3-target-error');
    const save=async()=>{const data=new FormData(form);return api('/api/backups/target',{method:'PUT',body:JSON.stringify({endpoint:data.get('endpoint'),bucket:data.get('bucket'),region:data.get('region'),prefix:data.get('prefix'),access_key:data.get('access_key'),secret_key:data.get('secret_key'),enabled:form.elements.enabled.checked})})};
    form.onsubmit=async event=>{event.preventDefault();error.textContent='';try{await save();closeModal();toast('S3 destination saved','success');await renderBackupStorage()}catch(err){error.textContent=err.message}};
    form.querySelector('#save-test-s3').onclick=async event=>{event.preventDefault();error.textContent='';const button=event.currentTarget;button.disabled=true;try{await save();await api('/api/backups/target/test',{method:'POST',body:'{}'});closeModal();toast('S3 destination saved and connection verified','success');await renderBackupStorage()}catch(err){error.textContent=err.message}finally{button.disabled=false}};
  }

  async function renderSchedules(s){
    const b=document.querySelector('#detail-body');
    const canBackup=(s.permissions||[]).includes('server.backup');
    const canControl=(s.permissions||[]).includes('server.control');
    const canConsole=(s.permissions||[]).includes('server.console');
    const canSchedule=(s.permissions||[]).includes('server.schedule');
    let messageTemplates=[];
    if(canSchedule){try{messageTemplates=await api('/api/message-templates')}catch{}}
    let restartWarnings=[];
    let canSkipIfPlayersOnline=false;
    let scheduleOptionsError=false;
    if(canControl){try{const options=await api(`/api/servers/${s.id}/schedule-options`);restartWarnings=options.restart_warnings||[];canSkipIfPlayersOnline=options.can_skip_if_players_online===true}catch{scheduleOptionsError=true}}
    const canRestart=canControl&&!scheduleOptionsError;
    const canMessage=canSchedule&&messageTemplates.length>0&&['minecraft-java','minecraft-bedrock'].includes(s.gameskill_id);
    const canCreate=canBackup||canControl||canConsole||canMessage;
    function warningSeconds(value){
      const units={h:3600,m:60,s:1,ms:.001,us:.000001,'µs':.000001,ns:.000000001};
      const parts=[...String(value||'').matchAll(/(\d+(?:\.\d+)?)(ms|us|µs|ns|h|m|s)/g)];
      if(!parts.length||parts.map(x=>x[0]).join('')!==String(value))return 0;
      const total=parts.reduce((sum,part)=>sum+Number(part[1])*units[part[2]],0);
      return Number.isInteger(total)&&total>0&&total<=86400?total:0;
    }
    const warningOptions=[...new Set(restartWarnings.map(w=>warningSeconds(w.at)).filter(Boolean))].sort((a,b)=>a-b);
    const defaultWarning=warningOptions.includes(60)?60:(warningOptions[0]||0);
    const warningLabel=value=>value%3600===0?`${value/3600} hour${value===3600?'':'s'}`:value%60===0?`${value/60} minute${value===60?'':'s'}`:`${value} seconds`;
    b.innerHTML=`<section class="panel-card schedule-panel"><div class="panel-head"><div><h2>Schedules</h2><p>Run backups, server actions, console commands, and messages on a recurring schedule.</p></div><button class="button primary" id="add-backup-schedule" ${canCreate?'':'disabled'}>+ Add schedule</button></div><div class="backup-note">Cron runs in the panel host's local time. Use five fields (minute hour day month weekday) or six fields with seconds first. Backups require the server to be stopped. Restart warnings use this template's configured commands.</div>${scheduleOptionsError?'<div class="schedule-permission-note">Restart options could not be loaded. Refresh this view before creating a restart schedule.</div>':''}${canCreate?'':'<div class="schedule-permission-note">Grant an action permission or add a message template, plus server.schedule, to create schedules.</div>'}<div class="schedule-list" id="schedule-list"><div class="files-empty">Loading schedules…</div></div></section>`;
    const host=document.querySelector('#schedule-list');
    const add=document.querySelector('#add-backup-schedule');
    add.onclick=()=>{
      const actions=[...(canBackup?['backup']:[]),...(canControl?['start','stop']:[]),...(canRestart?['restart']:[]),...(canConsole?['command']:[]),...(canMessage?['message']:[])];
      const initial=actions[0]||'backup';
      const actionLabel=action=>({backup:'Create backup',restart:'Restart server',start:'Start server',stop:'Stop server',command:'Send console command',message:'Send a message'}[action]||action);
      const defaultName=action=>({backup:'Scheduled backup',restart:'Scheduled restart',start:'Scheduled start',stop:'Scheduled stop',command:'Scheduled command',message:'Scheduled message'}[action]||'Scheduled action');
      modal(`<div class="modal-heading"><div><div class="eyebrow">AUTOMATION</div><h2>New schedule</h2></div><button class="icon-button" data-close>×</button></div><form id="create-backup-schedule"><label>Action<select name="action">${actions.map(action=>`<option value="${action}">${actionLabel(action)}</option>`).join('')}</select></label><label>Schedule name<input name="name" maxlength="80" value="${defaultName(initial)}" required></label><label>Cron expression<input name="cron" value="0 3 * * *" required><small>Host-local time · five fields, or six with leading seconds</small></label><div id="restart-schedule-fields" ${initial==='restart'?'':'hidden'}><label class="checkline"><input type="checkbox" name="warn_players" ${defaultWarning?'checked':''} ${warningOptions.length?'':'disabled'}>Warn players before restart</label><label>Warning countdown<select name="warning_seconds" ${defaultWarning?'':'disabled'}>${warningOptions.map(value=>`<option value="${value}" ${value===defaultWarning?'selected':''}>${warningLabel(value)}</option>`).join('')}</select></label>${warningOptions.length?'':'<small>This template has no restart warning commands; the restart will run immediately.</small>'}${canSkipIfPlayersOnline?'<label class="checkline"><input type="checkbox" name="skip_if_players_online">Skip the restart if players are online</label>':''}</div><div id="command-schedule-fields" ${initial==='command'?'':'hidden'}><label>Console command<input name="command" maxlength="4096" required placeholder="say Maintenance starts soon"></label><small>The command is stored encrypted and sent only while the server is running.</small></div><div id="message-schedule-fields" ${initial==='message'?'':'hidden'}><label>Message template<select name="message_template_id">${messageTemplates.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('')}</select></label><div id="message-template-values"></div><small>Messages use Minecraft chat commands and remain encrypted in the schedule.</small></div><label class="checkline"><input type="checkbox" name="enabled" checked> Enable schedule</label><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary" type="submit">Save schedule</button></div></form>`);
      const formEl=document.querySelector('#create-backup-schedule');
      const actionSelect=formEl.elements.action;
      const restartFields=formEl.querySelector('#restart-schedule-fields');
      const commandFields=formEl.querySelector('#command-schedule-fields');
      const messageFields=formEl.querySelector('#message-schedule-fields');
      const messageTemplateSelect=formEl.elements.message_template_id;
      const messageValuesHost=formEl.querySelector('#message-template-values');
      const commandInput=formEl.elements.command;
      commandInput.disabled=actionSelect.value!=='command';
      commandInput.required=actionSelect.value==='command';
      messageTemplateSelect.disabled=actionSelect.value!=='message';
      const drawMessageValues=()=>{
        const selected=messageTemplates.find(item=>item.id===messageTemplateSelect.value);
        messageValuesHost.innerHTML=(selected?.parameters||[]).filter(parameter=>parameter!=='server_name').map(parameter=>`<label>${parameter==='minutes'?'Minutes':'Seconds'}<input name="message_${esc(parameter)}" type="number" min="0" max="${parameter==='minutes'?10080:86400}" value="${parameter==='minutes'?5:60}" required></label>`).join('');
      };
      messageTemplateSelect.onchange=drawMessageValues;
      drawMessageValues();
      actionSelect.onchange=()=>{
        const restart=actionSelect.value==='restart';
        const command=actionSelect.value==='command';
        const message=actionSelect.value==='message';
        restartFields.hidden=!restart;
        commandFields.hidden=!command;
        messageFields.hidden=!message;
        commandInput.disabled=!command;
        commandInput.required=command;
        messageTemplateSelect.disabled=!message;
        formEl.elements.name.value=defaultName(actionSelect.value);
      };
      formEl.elements.warn_players.onchange=()=>{formEl.elements.warning_seconds.disabled=!formEl.elements.warn_players.checked};
      formEl.addEventListener('submit',async e=>{
        e.preventDefault();
        const form=new FormData(e.currentTarget),action=form.get('action');
        const body={name:form.get('name'),action,cron:form.get('cron'),enabled:form.has('enabled')};
        if(action==='restart'){body.warn_players=form.has('warn_players');body.skip_if_players_online=form.has('skip_if_players_online');if(body.warn_players)body.warning_seconds=Number(form.get('warning_seconds'))}
        if(action==='command')body.command=form.get('command');
        if(action==='message'){
          body.message_template_id=messageTemplateSelect.value;
          body.values={};
          const template=messageTemplates.find(item=>item.id===messageTemplateSelect.value);
          for(const parameter of template?.parameters||[])if(parameter!=='server_name')body.values[parameter]=Number(form.get(`message_${parameter}`));
        }
        try{await api(`/api/servers/${s.id}/schedules`,{method:'POST',body:JSON.stringify(body)});closeModal();toast('Schedule saved','success');await load()}catch(err){toast(err.message,'error')}
      });
    };
    async function load(){
      try{
        const items=await api(`/api/servers/${s.id}/schedules`);
        if(!items.length){host.innerHTML='<div class="files-empty">No schedules yet.</div>';return}
        host.innerHTML=items.map(item=>{const when=value=>value?new Date(value).toLocaleString():'Not run yet';const labels={backup:'Backup',restart:'Restart',start:'Start',stop:'Stop',command:'Console command',message:'Message'};const action=labels[item.action]||'Unknown action';const canChange=item.action==='backup'?canBackup:item.action==='command'?canConsole:item.action==='message'?canSchedule:canControl;return `<article class="schedule-row" data-schedule="${esc(item.id)}"><div class="schedule-summary"><b>${esc(item.name)}</b><small>${action}${item.action==='restart'&&item.warn_players?` · ${warningLabel(item.warning_seconds)} warning`:''}${item.action==='restart'&&item.skip_if_players_online?' · skip if players are online':''}</small><code>${esc(item.cron)}</code><span>${item.enabled?`Enabled · next ${esc(when(item.next_run))}`:'Disabled'}</span>${item.last_status?`<small>Last run · ${esc(when(item.last_run))} · ${esc(item.last_status)}${item.last_error?` · ${esc(item.last_error)}`:''}</small>`:'<small>No run recorded yet</small>'}</div><div class="schedule-actions"><button class="button subtle" data-schedule-op="runs">Run history</button><button class="button subtle" data-schedule-op="toggle" ${!item.enabled&&!canChange?'disabled':''}>${item.enabled?'Disable':'Enable'}</button><button class="button danger" data-schedule-op="delete">Delete</button></div><div class="schedule-runs" hidden></div></article>`}).join('');
        host.querySelectorAll('[data-schedule-op]').forEach(button=>button.onclick=async()=>{
          const row=button.closest('.schedule-row'),id=row.dataset.schedule,op=button.dataset.scheduleOp,item=items.find(x=>x.id===id);
          if(op==='delete'&&!confirm(`Delete the schedule “${item.name}”?`))return;
          button.disabled=true;
          try{
            if(op==='toggle')await api(`/api/servers/${s.id}/schedules/${id}`,{method:'PUT',body:JSON.stringify({enabled:!item.enabled})});
            if(op==='delete')await api(`/api/servers/${s.id}/schedules/${id}`,{method:'DELETE'});
            if(op==='runs'){const runs=await api(`/api/servers/${s.id}/schedules/${id}/runs`),box=row.querySelector('.schedule-runs');box.hidden=false;box.innerHTML=runs.length?runs.map(run=>`<div><b>${esc(when(run.started_at))} · ${esc(run.status)}</b><small>${esc(run.detail||'No details')}</small></div>`).join(''):'<div class="muted-copy">No runs recorded yet.</div>';button.disabled=false;return}
            await load();
          }catch(e){toast(e.message,'error');button.disabled=false}
        });
      }catch(e){host.innerHTML=`<div class="files-empty error-text">${esc(e.message)}</div>`}
    }
    const when=value=>value?new Date(value).toLocaleString():'Not run yet';
    await load();
  }

  function renderWatchdogSettings(s,r){
    if(!r?.query)return;
    const grid=document.querySelector('#detail-body .settings-grid');
    if(!grid)return;
    const card=document.createElement('section');
    card.className='panel-card settings-card watchdog-card';
    card.style.gridColumn='1 / -1';
    card.innerHTML=`<div class="panel-head"><div><h2>Automatic recovery</h2><p>Restart this server when its player query stops responding.</p></div>${s.watchdog_quarantined?'<span class="status-badge bad"><i></i>PAUSED</span>':''}</div><form id="watchdog-form"><label class="checkline"><input type="checkbox" name="enabled" ${s.watchdog_enabled?'checked':''}>Enable automatic recovery</label><p class="muted-copy">Docklight checks every 20 seconds. Three failed checks trigger a restart, with a 4-minute cooldown. Five successful restarts within 30 minutes pause recovery until you manually start or stop the server.</p><div id="watchdog-error" class="form-error" role="alert"></div><div class="form-actions"><span class="muted-copy">Requires this template’s player query protocol.</span><button class="button primary" type="submit">Save recovery settings</button></div></form>`;
    grid.append(card);
    grid.querySelector('#watchdog-form').onsubmit=async e=>{
      e.preventDefault();
      const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),error=form.querySelector('#watchdog-error');
      error.textContent='';button.disabled=true;
      try{
        await api(`/api/servers/${s.id}/watchdog`,{method:'PUT',body:JSON.stringify({enabled:form.elements.enabled.checked})});
        toast('Automatic recovery settings saved','success');
        await refresh();state.selected=state.servers.find(x=>x.id===s.id);render();
      }catch(err){error.textContent=err.message;button.disabled=false}
    };
  }

  async function renderCrashHistory(s){const b=document.querySelector('#detail-body');b.innerHTML=`<section class="panel-card crash-history"><div class="panel-head"><div><h2>Container incidents</h2><p>Confirmed exits and missing containers recorded by Docklight.</p></div></div><div class="crash-list" id="crash-list"><div class="files-empty">Loading history…</div></div></section>`;const host=b.querySelector('#crash-list');try{const rows=await api(`/api/servers/${s.id}/crashes`);host.innerHTML=rows.length?rows.map(item=>`<article class="crash-row"><div><b>${item.reason==='container_missing'?'Container missing':'Unexpected container exit'}</b><small>${esc(new Date(item.detected_at).toLocaleString())} · ${item.exit_code>=0?`exit code ${item.exit_code}`:'exit code unavailable'}</small></div><p>${esc(item.message)}</p></article>`).join(''):'<div class="files-empty">No unexpected container exits have been recorded.</div>'}catch(e){host.innerHTML=`<div class="files-empty error-text">${esc(e.message)}</div>`}}
  async function renderOverview(s){const b=document.querySelector('#detail-body');let stats={running:s.status==='running',cpu_percent:0,memory_mb:0};if(s.status==='running'){try{stats=await api(`/api/servers/${s.id}/stats`)}catch{}}if(!b)return;let stackMarkup='';const stackServices=s.stack_services||[];if(stackServices.length){const running=stackServices.filter(service=>service.status==='running').length;stackMarkup='<section class="panel-card info-card"><div class="panel-head"><div><h2>Private services</h2><p>Sidecars on this server network</p></div><span class="status-badge '+(stackServices.some(service=>service.status==='error')?'bad':running===stackServices.length?'good':'muted')+'"><i></i>'+running+' / '+stackServices.length+' up</span></div><div class="info-rows">'+stackServices.map(service=>{const [label,kind]=statusInfo(service.status);return '<div><span>'+esc(service.name)+(service.error_message?'<small class="muted-copy">'+esc(service.error_message)+'</small>':'')+'</span><span class="stack-service-tools"><span class="status-badge '+kind+'"><i></i>'+esc(label)+'</span>'+(s.permissions?.includes('server.view')?'<button class="button link" data-stack-logs="'+esc(service.name)+'">Logs</button>':'')+'</span></div>'}).join('')+'</div></section>'}b.innerHTML=`<div class="overview-grid"><section class="panel-card"><div class="panel-head"><div><h2>Resource usage</h2><p>Live Docker container metrics</p></div><span class="live-indicator"><i></i> LIVE</span></div><div class="resource-row"><div class="resource-item"><div class="resource-name"><span>CPU</span><b>${stats.running?`${Number(stats.cpu_percent).toFixed(1)}%`:'—'}</b></div><div class="resource-bar"><i style="width:${Math.min(100,Number(stats.cpu_percent)||0)}%"></i></div><small>${s.cpu_limit?`Limit ${s.cpu_limit} cores`:'No CPU limit set'}</small></div><div class="resource-item"><div class="resource-name"><span>MEMORY</span><b>${stats.running?`${Number(stats.memory_mb||0).toFixed(0)} MB`:'—'}</b></div><div class="resource-bar blue"><i style="width:${s.memory_limit_mb?Math.min(100,(stats.memory_mb/s.memory_limit_mb)*100):0}%"></i></div><small>${s.memory_limit_mb?`Limit ${fmt(s.memory_limit_mb)} MB`:'No memory limit set'}</small></div></div></section><section class="panel-card"><div class="panel-head"><div><h2>Connection</h2><p>Allocated host ports</p></div><span class="connection-icon">↗</span></div><div class="port-list">${Object.entries(s.ports||{}).map(([name,port])=>`<div class="port-line"><span class="port-name"><i class="port-dot"></i>${esc(name)}</span><code>${fmt(port)}</code><button data-copy="${fmt(port)}" title="Copy port">▢</button></div>`).join('')||'<div class="muted-copy">This template has no published ports.</div>'}</div></section><section class="panel-card info-card"><div class="panel-head"><div><h2>Server details</h2><p>Runtime and configuration</p></div></div><div class="info-rows"><div><span>Template</span><b>${esc(runeName(s.gameskill_id))}</b></div><div><span>Server ID</span><code>${esc(s.id)}</code></div><div><span>Installation</span><b>${s.installed?'Ready':'Not installed'}</b></div><div><span>Players online</span><b id="players-online">${state.runes.find(r=>r.id===s.gameskill_id)?.query?'Loading…':'Not available'}</b></div></div></section>${stackMarkup}</div>`;b.querySelectorAll('[data-copy]').forEach(el=>el.addEventListener('click',()=>navigator.clipboard.writeText(el.dataset.copy).then(()=>toast('Port copied','success'))));b.querySelectorAll('[data-stack-logs]').forEach(el=>el.addEventListener('click',()=>openStackServiceLogs(s,el.dataset.stackLogs)));if(s.status==='running'&&state.runes.find(r=>r.id===s.gameskill_id)?.query){api(`/api/servers/${s.id}/query`).then(x=>{const p=document.querySelector('#players-online');if(p)p.textContent=`${fmt(x.online)} / ${fmt(x.max)}`}).catch(()=>{const p=document.querySelector('#players-online');if(p)p.textContent='Query unavailable'})}setTimeout(async()=>{if(state.selected?.id===s.id&&s.status==='running'&&document.querySelector('[data-tab="overview"]')?.classList.contains('active')){try{const updated=await api(`/api/servers/${s.id}`);state.selected=updated;state.servers=state.servers.map(server=>server.id===updated.id?updated:server);renderOverview(updated)}catch{}}},10000);}
  function openStackServiceLogs(s,service){
    modal(`<div class="modal-heading"><div><div class="eyebrow">PRIVATE SERVICE</div><h2>${esc(service)} logs</h2></div><button class="icon-button" data-close aria-label="Close logs">×</button></div><div class="console-top"><span class="console-subtitle">Latest output · secrets are redacted</span><span class="live-indicator" id="stack-log-state"><i></i> CONNECTING</span></div><div class="console-screen stack-log-screen" id="stack-log-screen"><div class="console-placeholder">Connecting to private service logs…</div></div>`);
    const layer=document.querySelector('.modal-layer'),screen=document.querySelector('#stack-log-screen'),indicator=document.querySelector('#stack-log-state');
    const protocol=location.protocol==='https:'?'wss:':'ws:';
    const ws=new WebSocket(`${protocol}//${location.host}/api/servers/${encodeURIComponent(s.id)}/stack-services/${encodeURIComponent(service)}/logs`);
    state.socket=ws;
    const close=()=>{if(state.socket===ws)state.socket=null;if(ws.readyState<2){try{ws.close()}catch{}}closeModal()};
    layer.querySelectorAll('[data-close], [data-backdrop]').forEach(el=>el.onclick=close);
    ws.onopen=()=>{if(indicator){indicator.innerHTML='<i></i> LIVE';indicator.classList.add('connected')}};
    ws.onmessage=event=>{if(screen.querySelector('.console-placeholder'))screen.replaceChildren();const row=document.createElement('div');row.className='log-line';row.textContent=event.data;screen.append(row);if(screen.children.length>2000)screen.firstElementChild.remove();screen.scrollTop=screen.scrollHeight};
    ws.onerror=()=>{if(screen.querySelector('.console-placeholder'))screen.textContent='Private service logs could not connect. Check the server and your access.'};
    ws.onclose=()=>{if(indicator){indicator.innerHTML='<i></i> STREAM ENDED';indicator.classList.remove('connected')}};
  }
  const runeName=(id)=>state.runes.find(r=>r.id===id)?.name||id;
  function renderConsole(s){const b=document.querySelector('#detail-body');b.innerHTML=`<section class="console-wrap"><div class="console-top"><div><b>Live console</b><span class="console-subtitle">Container output and server commands</span></div><span class="live-indicator"><i></i> CONNECTING</span></div><div class="console-screen" id="console-screen"><div class="console-placeholder">Connecting to server output…</div></div><form id="command-form" class="console-input"><span class="prompt">›</span><input name="command" placeholder="Enter a server command…" autocomplete="off" ${s.status==='running'?'':'disabled'}><button class="button primary" type="submit" ${s.status==='running'?'':'disabled'}>Send <span>↗</span></button></form><div class="console-foot"><span>Commands are sent to the server's standard input.</span><button class="button link" id="clear-log">Clear view</button></div></section>`;const screen=document.querySelector('#console-screen');const protocol=location.protocol==='https:'?'wss:':'ws:';const ws=new WebSocket(`${protocol}//${location.host}/api/servers/${s.id}/console`);state.socket=ws;ws.onopen=()=>{document.querySelector('.console-wrap .live-indicator').innerHTML='<i></i> CONNECTED';document.querySelector('.console-wrap .live-indicator').classList.add('connected');};ws.onmessage=e=>{if(screen.querySelector('.console-placeholder'))screen.innerHTML='';const row=document.createElement('div');row.className='log-line';row.textContent=e.data;screen.append(row);screen.scrollTop=screen.scrollHeight;};ws.onerror=()=>{if(!screen.textContent)screen.textContent='The live console could not connect. Check the server state and permission.'};document.querySelector('#command-form').addEventListener('submit',e=>{e.preventDefault();const input=e.currentTarget.elements.command;if(!input.value.trim()||ws.readyState!==1)return;ws.send(JSON.stringify({type:'command',command:input.value}));input.value='';});document.querySelector('#clear-log').addEventListener('click',()=>screen.innerHTML='');}
  async function renderFiles(s){const b=document.querySelector('#detail-body');b.innerHTML=`<section class="file-panel"><div class="file-toolbar"><div><h2>Server files</h2><p>Browse and edit the server's data directory.</p></div><div class="file-actions"><label class="button subtle file-upload">↑ Upload<input type="file" id="upload-file" hidden></label><button class="button subtle" id="new-folder">+ Folder</button></div></div><div class="breadcrumb" id="file-breadcrumb"></div><div class="file-table"><div class="file-table-head"><span>NAME</span><span>SIZE</span><span>MODIFIED</span><span></span></div><div id="file-rows" class="file-rows"></div></div></section>`;document.querySelector('#new-folder').onclick=async()=>{const name=prompt('New folder name');if(!name)return;try{await api(`/api/servers/${s.id}/files/mkdir`,{method:'POST',body:JSON.stringify({path:joinPath(state.filePath,name)})});loadFiles(s)}catch(e){toast(e.message,'error')}};document.querySelector('#upload-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;const form=new FormData();form.set('path',state.filePath);form.set('file',f);try{await api(`/api/servers/${s.id}/files/upload`,{method:'POST',body:form});toast('File uploaded','success');loadFiles(s)}catch(err){toast(err.message,'error')}e.target.value='';};loadFiles(s);}
  const joinPath=(a,b)=>[a,b].filter(Boolean).join('/');
  async function loadFiles(s){try{const x=await api(`/api/servers/${s.id}/files?path=${encodeURIComponent(state.filePath)}`);const crumbs=['<button data-path="">data</button>',...state.filePath.split('/').filter(Boolean).map((p,i,a)=>`<button data-path="${esc(a.slice(0,i+1).join('/'))}">${esc(p)}</button>`)];document.querySelector('#file-breadcrumb').innerHTML=crumbs.join('<span>›</span>');document.querySelectorAll('#file-breadcrumb [data-path]').forEach(b=>b.onclick=()=>{state.filePath=b.dataset.path;loadFiles(s)});const host=document.querySelector('#file-rows');host.innerHTML=x.entries.length?x.entries.map(e=>`<div class="file-row"><button class="file-name" data-file="${esc(e.path)}" data-dir="${e.directory}"><span class="file-icon ${e.directory?'folder':''}">${e.directory?'▱':'▤'}</span><b>${esc(e.name)}</b></button><span>${e.directory?'—':formatBytes(e.size)}</span><span>${new Date(e.modified).toLocaleString()}</span><button class="file-menu" data-delete="${esc(e.path)}" title="Delete">···</button></div>`).join(''):'<div class="files-empty">This directory is empty.</div>';host.querySelectorAll('[data-file]').forEach(el=>el.onclick=()=>{if(el.dataset.dir==='true'){state.filePath=el.dataset.file;loadFiles(s)}else openEditor(s,el.dataset.file)});host.querySelectorAll('[data-delete]').forEach(el=>el.onclick=async()=>{if(!confirm(`Delete ${el.dataset.delete}?`))return;try{await api(`/api/servers/${s.id}/files/content?path=${encodeURIComponent(el.dataset.delete)}`,{method:'DELETE'});loadFiles(s)}catch(e){toast(e.message,'error')}});}catch(e){document.querySelector('#file-rows').innerHTML=`<div class="files-empty error-text">${esc(e.message)}</div>`}}
  function formatBytes(n){if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;return `${(n/1024/1024).toFixed(1)} MB`;}
  async function openEditor(s,path){try{const x=await api(`/api/servers/${s.id}/files/content?path=${encodeURIComponent(path)}`);modal(`<div class="modal-heading"><div><div class="eyebrow">FILE EDITOR</div><h2>${esc(path)}</h2></div><button class="icon-button" data-close>×</button></div><textarea class="editor-area" id="editor-content" spellcheck="false">${esc(x.content)}</textarea><div class="modal-actions"><span class="muted-copy">Changes are written directly to the server data directory.</span><button class="button primary" id="save-file">Save changes</button></div>`);document.querySelector('[data-close]').onclick=closeModal;document.querySelector('#save-file').onclick=async()=>{try{await api(`/api/servers/${s.id}/files/content`,{method:'PUT',body:JSON.stringify({path,content:document.querySelector('#editor-content').value})});closeModal();toast('File saved','success')}catch(e){toast(e.message,'error')}};}catch(e){toast(e.message,'error')}}
  function renderSettings(s){const b=document.querySelector('#detail-body');const r=state.runes.find(x=>x.id===s.gameskill_id);b.innerHTML=`<div class="settings-grid"><section class="panel-card settings-card"><div class="panel-head"><div><h2>General settings</h2><p>Name and resource limits for this server</p></div></div><form id="settings-form"><label>Server name<input name="name" value="${esc(s.name)}" maxlength="80" required></label><div class="two-fields"><label>CPU limit <small>cores, 0 for unlimited</small><input name="cpu_limit" type="number" min="0" max="64" step="0.1" value="${s.cpu_limit||0}"></label><label>Memory limit <small>MB, 0 for unlimited</small><input name="memory_limit_mb" type="number" min="0" value="${s.memory_limit_mb||0}"></label></div><h3>Template settings</h3>${(r?.variables||[]).map(v=>{const value=s.env?.[v.key]||v.default||'';return `<label>${esc(v.name||v.key)}${v.required?'<sup>*</sup>':''}${v.hint?`<small>${esc(v.hint)}</small>`:''}${v.type==='select'?`<select name="var:${esc(v.key)}">${(v.options||[]).map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:v.type==='bool'?`<select name="var:${esc(v.key)}"><option value="true" ${String(value)==='true'?'selected':''}>Enabled</option><option value="false" ${String(value)==='false'?'selected':''}>Disabled</option></select>`:`<input name="var:${esc(v.key)}" type="${v.secret?'password':'text'}" value="${v.secret?'':esc(value)}" placeholder="${v.secret?'Stored securely · leave empty to keep current':esc(value)}" ${v.required&&!v.secret?'required':''}>`}</label>`}).join('')}<div class="form-actions"><span class="muted-copy">Secret values are encrypted and never shown again.</span><button class="button primary" type="submit">Save settings</button></div></form></section><section class="panel-card danger-zone"><div class="panel-head"><div><h2>Danger zone</h2><p>Remove this server and its data</p></div></div><div class="danger-row"><div><b>Delete server</b><small>Stops its container and permanently removes its data.</small></div><button class="button danger" id="delete-server">Delete</button></div></section></div>`;renderWatchdogSettings(s,r);document.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget),env={};for(const [k,v] of data.entries())if(k.startsWith('var:')&&v!=='')env[k.slice(4)]=v;const payload={name:data.get('name'),cpu_limit:Number(data.get('cpu_limit')),memory_limit_mb:Number(data.get('memory_limit_mb')),env};try{await api(`/api/servers/${s.id}`,{method:'PUT',body:JSON.stringify(payload)});toast('Settings saved','success');await refresh();state.selected=state.servers.find(x=>x.id===s.id);render()}catch(err){toast(err.message,'error')}};document.querySelector('#delete-server').onclick=async()=>{if(!confirm(`Delete ${s.name} and all of its data and local backups?`))return;try{await api(`/api/servers/${s.id}`,{method:'DELETE'});state.selected=null;await refresh();render()}catch(e){toast(e.message,'error')}};}

  function renderRunes(){
    const v=document.querySelector('#view');
    const admin=state.user.role==='admin';
    v.innerHTML=`<div class="page-heading"><div><div class="eyebrow">DECLARATIVE BLUEPRINTS</div><h1>Templates</h1><p>Reusable configurations for games and apps that run in containers.</p></div>${admin?'<div class="detail-actions"><button class="button subtle" id="manage-message-templates">Message templates</button><button class="button subtle" id="upload-rune">↑ Import YAML</button></div>':''}</div><div class="rune-grid">${state.runes.map(r=>`<article class="rune-card"><div class="rune-card-top"><div class="rune-symbol">▤</div><span class="rune-category">${esc(r.category||'Default')}</span></div><h3>${esc(r.name)}</h3><p>${esc(r.description||'Ready-to-run container configuration.')}</p><div class="rune-tags"><span>${r.ports?.length||0} ports</span><span>v${r.version}</span>${r.builtin?'<span class="builtin-tag">Built in</span>':''}</div><button class="rune-create" data-rune="${esc(r.id)}">Create server <span>→</span></button></article>`).join('')}</div>`;
    v.querySelectorAll('[data-rune]').forEach(b=>b.onclick=()=>newServerModal(b.dataset.rune));
    v.querySelector('#manage-message-templates')?.addEventListener('click',manageMessageTemplates);
    v.querySelector('#upload-rune')?.addEventListener('click',()=>{modal(`<div class="modal-heading"><div><div class="eyebrow">IMPORT TEMPLATE</div><h2>Upload a template</h2></div><button class="icon-button" data-close>×</button></div><p class="muted-copy">YAML is validated before it is saved. Built-in template IDs are protected.</p><textarea id="rune-yaml" class="yaml-area" placeholder="gameskill:\n  id: my-app\n  name: My App\n  docker:\n    image: example/app:latest\n  startup:\n    command: exec app\n"></textarea><div class="modal-actions"><button class="button subtle" data-close>Cancel</button><button class="button primary" id="save-rune">Validate & import</button></div>`);document.querySelector('[data-close]').onclick=closeModal;document.querySelector('#save-rune').onclick=async()=>{try{const x=await api('/api/gameskills',{method:'POST',body:document.querySelector('#rune-yaml').value});closeModal();toast(`Imported ${x.name}`,'success');await refresh();render()}catch(e){toast(e.message,'error')}};});
  }
  async function manageMessageTemplates(){
    let items=[];
    try{items=await api('/api/message-templates')}catch(e){toast(e.message,'error');return}
    modal(`<div class="modal-heading"><div><div class="eyebrow">SCHEDULED MESSAGES</div><h2>Message templates</h2></div><button class="icon-button" data-close>×</button></div><p class="muted-copy">Each template is one Minecraft console command. Available placeholders: <code>{{server_name}}</code>, <code>{{minutes}}</code>, and <code>{{seconds}}</code>.</p><div class="message-template-list">${items.map(item=>`<article class="schedule-row"><div class="schedule-summary"><b>${esc(item.name)}</b><small>${item.builtin?'Built in':'Custom'} · ${(item.parameters||[]).map(esc).join(', ')||'No values required'}</small><code>${esc(item.body||'Template body is visible to administrators only.')}</code></div>${item.builtin?'':'<div class="schedule-actions"><button class="button subtle" data-message-edit="'+esc(item.id)+'">Edit</button><button class="button danger" data-message-delete="'+esc(item.id)+'">Delete</button></div>'}</article>`).join('')}</div><div class="modal-actions"><button class="button subtle" data-close>Close</button><button class="button primary" id="add-message-template">+ New template</button></div>`);
    document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);
    document.querySelector('#add-message-template').onclick=()=>editMessageTemplate(null);
    document.querySelectorAll('[data-message-edit]').forEach(button=>button.onclick=()=>editMessageTemplate(items.find(item=>item.id===button.dataset.messageEdit)));
    document.querySelectorAll('[data-message-delete]').forEach(button=>button.onclick=async()=>{const item=items.find(entry=>entry.id===button.dataset.messageDelete);if(!confirm(`Delete custom message template “${item.name}”?`))return;try{await api(`/api/message-templates/${item.id}`,{method:'DELETE'});toast('Message template deleted','success');await manageMessageTemplates()}catch(e){toast(e.message,'error')}});
  }
  function editMessageTemplate(item){
    const editing=Boolean(item);
    modal(`<div class="modal-heading"><div><div class="eyebrow">${editing?'EDIT TEMPLATE':'NEW TEMPLATE'}</div><h2>${editing?'Edit message template':'Create message template'}</h2></div><button class="icon-button" data-close>×</button></div><form id="message-template-form"><label>Template name<input name="name" maxlength="80" required value="${esc(item?.name||'')}"></label><label>Minecraft console command<textarea name="body" class="editor-area" required maxlength="4096" placeholder="say {{server_name}} maintenance starts in {{minutes}} minutes">${esc(item?.body||'')}</textarea><small>One line, with optional placeholders {{server_name}}, {{minutes}}, and {{seconds}}. Custom templates are available in Minecraft schedules.</small></label><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">${editing?'Save template':'Create template'}</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);
    document.querySelector('#message-template-form').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const body=JSON.stringify({name:form.get('name'),body:form.get('body')});try{await api(editing?`/api/message-templates/${item.id}`:'/api/message-templates',{method:editing?'PUT':'POST',body});closeModal();toast(editing?'Message template updated':'Message template created','success');await manageMessageTemplates()}catch(e){toast(e.message,'error')}};
  }
  async function newServerModal(runeID){let options=state.runes;if(!options.length)await refresh();const selected=runeID||options[0]?.id;const variableForm=(r)=> (r?.variables||[]).map(v=>{const value=v.secret?'':(v.default??'');return `<label>${esc(v.name||v.key)}${v.required?'<sup>*</sup>':''}${v.hint?`<small>${esc(v.hint)}</small>`:''}${v.type==='select'?`<select name="${esc(v.key)}">${(v.options||[]).map(o=>`<option ${o===String(value)?'selected':''}>${esc(o)}</option>`).join('')}</select>`:v.type==='bool'?`<select name="${esc(v.key)}"><option value="true" ${String(value)==='true'?'selected':''}>Enabled</option><option value="false" ${String(value)==='false'?'selected':''}>Disabled</option></select>`:`<div class="input-with-button"><input name="${esc(v.key)}" type="${v.secret?'password':'text'}" value="${esc(value)}" placeholder="${v.secret?'Required secret value':esc(value)}" ${v.required?'required':''}>${v.secret?`<button type="button" data-generate="${esc(v.key)}" title="Generate a secure value">⤨</button>`:''}</div>`}</label>`}).join('');
    const draw=async id=>{try{const r=await api(`/api/gameskills/${id}`);document.querySelector('#rune-fields').innerHTML=variableForm(r)||'<p class="muted-copy">This template has no settings to configure.</p>';document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=()=>{const input=document.querySelector(`[name="${CSS.escape(b.dataset.generate)}"]`);const bytes=crypto.getRandomValues(new Uint8Array(24));const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%_-';input.value=Array.from(bytes,x=>alphabet.charAt(x%alphabet.length)).join('');});}catch(e){toast(e.message,'error')}};
    modal(`<div class="modal-heading"><div><div class="eyebrow">NEW DEPLOYMENT</div><h2>Create a server</h2></div><button class="icon-button" data-close>×</button></div><form id="create-server-form"><label>Server name<input name="name" required maxlength="80" placeholder="My server"></label><label>Template<select name="gameskill_id" id="rune-select">${options.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.name)} · ${esc(r.category||'Default')}</option>`).join('')}</select></label><div id="rune-fields"></div><div class="two-fields"><label>CPU limit <small>cores, 0 for unlimited</small><input name="cpu_limit" type="number" min="0" max="64" step="0.1" value="0"></label><label>Memory limit <small>MB, 0 for unlimited</small><input name="memory_limit_mb" type="number" min="0" value="0"></label></div><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary" type="submit">Create server <span>→</span></button></div></form>`);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelector('#rune-select').onchange=e=>draw(e.target.value);await draw(selected);document.querySelector('#create-server-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget),env={};const currentRune=await api(`/api/gameskills/${data.get('gameskill_id')}`);for(const v of currentRune.variables||[]){const value=data.get(v.key);if(value!==null&&value!=='')env[v.key]=value;}try{const s=await api('/api/servers',{method:'POST',body:JSON.stringify({name:data.get('name'),gameskill_id:data.get('gameskill_id'),env,cpu_limit:Number(data.get('cpu_limit')),memory_limit_mb:Number(data.get('memory_limit_mb'))})});closeModal();await refresh();state.selected=state.servers.find(x=>x.id===s.id);render();toast('Server created. Run install to continue.','success')}catch(err){toast(err.message,'error')}};}

  async function renderUsers(){const v=document.querySelector('#view');if(state.user.role!=='admin'){v.innerHTML='<div class="page-heading"><h1>Not available</h1></div>';return;}try{state.users=await api('/api/users')}catch(e){v.innerHTML=`<h1>Error</h1><p>${esc(e.message)}</p>`;return;}v.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Users & access</h1><p>Give each person access only to the servers they need.</p></div><button class="button primary" id="add-user">+ Add user</button></div><div class="panel-card users-table"><div class="user-table-head"><span>USER</span><span>ROLE</span><span>2FA</span><span>STATUS</span><span></span></div>${state.users.map(u=>`<div class="user-row"><div><span class="avatar small">${esc(u.username[0].toUpperCase())}</span><b>${esc(u.username)}</b></div><span><span class="role-badge">${esc(u.role)}</span></span><span>${u.totp_enabled?'<span class="good-text">Enabled</span>':'<span class="muted-copy">Not set</span>'}</span><span>${u.disabled?'<span class="status-badge bad"><i></i>Disabled</span>':'<span class="status-badge good"><i></i>Active</span>'}</span><button class="button subtle" data-user-edit="${esc(u.id)}">Manage</button></div>`).join('')}</div>`;document.querySelector('#add-user').onclick=()=>createUserModal();v.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>manageUser(b.dataset.userEdit));}
  function createUserModal(){modal(`<div class="modal-heading"><div><div class="eyebrow">NEW ACCOUNT</div><h2>Add a user</h2></div><button class="icon-button" data-close>×</button></div><form id="new-user-form"><label>Username<input name="username" required maxlength="64"></label><label>Temporary password<input name="password" type="password" minlength="12" autocomplete="new-password" required><small>At least 12 characters. Share it with the user privately.</small></label><label>Role<select name="role"><option value="user">User · scoped access</option><option value="admin">Administrator · full access</option></select></label><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">Create user</button></div></form>`);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelector('#new-user-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/users',{method:'POST',body:JSON.stringify(f)});closeModal();renderUsers();toast('User created','success')}catch(err){toast(err.message,'error')}};}
  async function manageUser(id){const u=state.users.find(x=>x.id===id);let grants=[];try{grants=(await api(`/api/users/${id}/permissions`)).grants||[]}catch{}const servers=state.servers;modal(`<div class="modal-heading"><div><div class="eyebrow">ACCOUNT & PERMISSIONS</div><h2>${esc(u.username)}</h2></div><button class="icon-button" data-close>×</button></div><div class="user-manage"><label>Role<select id="edit-role"><option value="user" ${u.role==='user'?'selected':''}>User</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator</option></select></label><label>New password <small>Leave empty to keep the current password</small><input id="edit-password" type="password" minlength="12" autocomplete="new-password"></label><label class="checkline"><input id="edit-disabled" type="checkbox" ${u.disabled?'checked':''}> Disable this account</label><div class="grant-heading"><h3>Server grants</h3><span>Applies at the API</span></div><div class="grant-list">${servers.map(s=>{const old=grants.find(g=>g.scope_type==='server'&&g.scope_id===s.id);return `<div class="grant-row"><div><b>${esc(s.name)}</b><small>${esc(s.gameskill_id)}</small></div><div class="grant-checks">${['server.view','server.control','server.console','server.files','server.backup','server.schedule','server.delete'].map(p=>`<label title="${p}"><input type="checkbox" data-grant="${esc(s.id)}" value="${p}" ${old?.permissions?.includes(p)?'checked':''}><span>${p.replace('server.','')}</span></label>`).join('')}</div></div>`}).join('')||'<p class="muted-copy">Create a server before assigning server-specific access.</p>'}</div><div class="modal-actions"><button class="button danger" id="delete-user">Delete user</button><button class="button primary" id="save-user">Save account & access</button></div></div>`);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);document.querySelector('#save-user').onclick=async()=>{const role=document.querySelector('#edit-role').value,password=document.querySelector('#edit-password').value,disabled=document.querySelector('#edit-disabled').checked;try{await api(`/api/users/${id}`,{method:'PUT',body:JSON.stringify({role,password,disabled})});const buckets={};document.querySelectorAll('[data-grant]').forEach(c=>{const server=c.dataset.grant;(buckets[server] ||= []).push(c.value)});const grantRows=Object.entries(buckets).filter(([,ps])=>ps.length).map(([server,permissions])=>({scope_type:'server',scope_id:server,permissions}));await api(`/api/users/${id}/permissions`,{method:'PUT',body:JSON.stringify({grants:grantRows})});closeModal();await renderUsers();toast('Account and permissions updated','success')}catch(e){toast(e.message,'error')}};document.querySelector('#delete-user').onclick=async()=>{if(!confirm(`Delete user ${u.username}?`))return;try{await api(`/api/users/${id}`,{method:'DELETE'});closeModal();await renderUsers();toast('User deleted','success')}catch(e){toast(e.message,'error')}};}
  async function renderAudit(){const v=document.querySelector('#view');try{const rows=await api('/api/audit');v.innerHTML=`<div class="page-heading"><div><div class="eyebrow">ACCOUNTABILITY</div><h1>Audit history</h1><p>Administrative actions recorded by the panel.</p></div></div><div class="panel-card audit-table"><div class="audit-head"><span>TIME</span><span>ACTOR</span><span>ACTION</span><span>TARGET</span><span>DETAIL</span></div>${rows.map(x=>`<div class="audit-row"><span>${esc(x.at)}</span><span>${esc(x.username||'system')}</span><code>${esc(x.action)}</code><span>${esc(x.target_id||'—')}</span><span>${esc(x.detail||'—')}</span></div>`).join('')||'<div class="files-empty">No actions recorded yet.</div>'}</div>`}catch(e){v.innerHTML=`<div class="page-heading"><h1>Audit history</h1><p class="error-text">${esc(e.message)}</p></div>`}}
  async function renderNotifications(){
    const view=document.querySelector('#view');
    try{
      const settings=await api('/api/notifications');
      view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">DELIVERY</div><h1>Notifications</h1><p>Send server and scheduler events to a secure webhook endpoint.</p></div></div><div class="notification-grid"><section class="panel-card notification-card"><div class="panel-head"><div><h2>Webhook channel</h2><p>${settings.enabled?'Delivery is enabled':'Delivery is disabled'}</p></div><span class="status-badge ${settings.enabled?'good':'muted'}"><i></i>${settings.enabled?'ACTIVE':'OFF'}</span></div><form id="notification-form"><label class="checkline"><input type="checkbox" name="enabled" ${settings.enabled?'checked':''}>Enable webhook notifications</label><div class="notification-events"><label class="checkline"><input type="checkbox" name="event" value="backup.success" ${(settings.events||[]).includes('backup.success')?'checked':''}>Successful backups</label><label class="checkline"><input type="checkbox" name="event" value="backup.failure" ${(settings.events||[]).includes('backup.failure')?'checked':''}>Failed backups</label><label class="checkline"><input type="checkbox" name="event" value="schedule.success" ${(settings.events||[]).includes('schedule.success')?'checked':''}>Successful scheduled actions</label><label class="checkline"><input type="checkbox" name="event" value="schedule.failure" ${(settings.events||[]).includes('schedule.failure')?'checked':''}>Failed scheduled actions</label></div><label>Webhook URL<input name="endpoint" type="url" autocomplete="off" placeholder="${settings.endpoint_configured?'Saved securely · leave blank to keep current':'https://example.com/webhook'}"><small>Encrypted at rest and never returned by the API. HTTPS is required; plain HTTP is allowed for localhost testing.</small></label><label>Signing secret<input name="signing_secret" type="password" autocomplete="new-password" placeholder="${settings.signing_secret_configured?'Saved securely · leave blank to keep current':'Optional HMAC signing key'}"><small>When set, each request includes an X-Docklight-Signature header.</small></label><label class="checkline"><input type="checkbox" name="clear_endpoint">Remove the saved webhook URL</label><label class="checkline"><input type="checkbox" name="clear_signing_secret">Remove the signing secret</label><div id="notifications-error" class="form-error" role="alert"></div><div class="form-actions"><button class="button subtle" type="button" id="test-notification">Save & send test</button><button class="button primary" type="submit">Save settings</button></div></form></section><aside class="panel-card notification-help"><h2>Events sent</h2><div class="notification-help-row"><b>backup.success</b><p>A manual or scheduled backup completed and passed integrity verification.</p></div><div class="notification-help-row"><b>backup.failure</b><p>A manual or scheduled backup failed. See the panel for its detailed error.</p></div><div class="notification-help-row"><b>schedule.success</b><p>A scheduled action completed. The payload includes its action and schedule ID.</p></div><div class="notification-help-row"><b>schedule.failure</b><p>A scheduled action failed. The payload links it to the schedule; sensitive run details are omitted.</p></div><p class="muted-copy">Requests are JSON POSTs. Redirects are not followed, and endpoint credentials stay encrypted with the panel secret key.</p></aside></div>`;
      const form=view.querySelector('#notification-form');
      const diskEvent=document.createElement('label');diskEvent.className='checkline';diskEvent.innerHTML=`<input type="checkbox" name="event" value="host.disk_low" ${(settings.events||[]).includes('host.disk_low')?'checked':''}>Low host storage`;
      form.querySelector('.notification-events').append(diskEvent);
      const crashEvent=document.createElement('label');crashEvent.className='checkline';crashEvent.innerHTML=`<input type="checkbox" name="event" value="server.crash" ${(settings.events||[]).includes('server.crash')?'checked':''}>Container crashes`;
      form.querySelector('.notification-events').append(crashEvent);
      const watchdogEvent=document.createElement('label');watchdogEvent.className='checkline';watchdogEvent.innerHTML=`<input type="checkbox" name="event" value="server.watchdog" ${(settings.events||[]).includes('server.watchdog')?'checked':''}>Automatic recovery`;
      form.querySelector('.notification-events').append(watchdogEvent);
      const diskHelp=document.createElement('div');diskHelp.className='notification-help-row';diskHelp.innerHTML='<b>host.disk_low</b><p>Fires below 10% free on the filesystem holding Docklight data. It rearms at 15% and names the server-data and backup paths to inspect.</p>';
      view.querySelector('.notification-help').prepend(diskHelp);
      const crashHelp=document.createElement('div');crashHelp.className='notification-help-row';crashHelp.innerHTML='<b>server.crash</b><p>Sent when Docklight confirms a container exit or missing container. Includes the server name and recorded incident details.</p>';
      view.querySelector('.notification-help').prepend(crashHelp);
      const watchdogHelp=document.createElement('div');watchdogHelp.className='notification-help-row';watchdogHelp.innerHTML='<b>server.watchdog</b><p>Sent when automatic recovery restarts a server, fails to restart it, or pauses after repeated heals.</p>';
      view.querySelector('.notification-help').prepend(watchdogHelp);
      const diskCard=document.createElement('section');diskCard.className='panel-card notification-help';diskCard.innerHTML='<h2>Panel storage</h2><p class="muted-copy">Reading current filesystem usage…</p>';
      view.querySelector('.notification-grid').append(diskCard);
      try{
        const disk=await api('/api/system/disk');
        const percent=new Intl.NumberFormat(undefined,{minimumFractionDigits:1,maximumFractionDigits:1}).format(disk.free_percent);
        const gib=value=>`${new Intl.NumberFormat(undefined,{maximumFractionDigits:1}).format(value/1073741824)} GiB`;
        diskCard.innerHTML=`<h2>Panel storage</h2><span class="status-badge ${disk.alert_active?'bad':'good'}"><i></i>${disk.alert_active?'Low space alert active':'Space looks healthy'}</span><p>${percent}% available · ${gib(disk.available_bytes)} of ${gib(disk.total_bytes)} free</p><code>${esc(disk.path)}</code><p class="muted-copy">Checked ${esc(new Date(disk.measured_at).toLocaleString())}. Alerts trigger below 10% and rearm at 15%.</p>`;
      }catch(e){diskCard.innerHTML=`<h2>Panel storage</h2><p class="error-text">${esc(e.message)}</p>`}
      const save=async()=>{const data=new FormData(form);return api('/api/notifications',{method:'PUT',body:JSON.stringify({enabled:form.elements.enabled.checked,events:Array.from(form.querySelectorAll('[name="event"]:checked'),x=>x.value),endpoint:data.get('endpoint'),signing_secret:data.get('signing_secret'),clear_endpoint:form.elements.clear_endpoint.checked,clear_signing_secret:form.elements.clear_signing_secret.checked})})};
      form.onsubmit=async e=>{e.preventDefault();const error=view.querySelector('#notifications-error');error.textContent='';try{await save();toast('Notification settings saved','success');await renderNotifications()}catch(err){error.textContent=err.message}};
      view.querySelector('#test-notification').onclick=async button=>{const error=view.querySelector('#notifications-error');error.textContent='';const b=button.currentTarget;b.disabled=true;try{await save();await api('/api/notifications/test',{method:'POST',body:'{}'});toast('Test notification delivered','success');await renderNotifications()}catch(err){error.textContent=err.message}finally{b.disabled=false}};
    }catch(e){view.innerHTML=`<div class="page-heading"><h1>Notifications</h1><p class="error-text">${esc(e.message)}</p></div>`}
  }
  function showProfile(){modal(`<div class="modal-heading"><div><div class="eyebrow">ACCOUNT</div><h2>${esc(state.user.username)}</h2></div><button class="icon-button" data-close>×</button></div><div class="profile-box"><span class="avatar large-avatar">${esc(state.user.username[0].toUpperCase())}</span><div><b>${esc(state.user.username)}</b><small>${state.user.role==='admin'?'Administrator':'Panel user'}</small></div></div><div class="profile-section"><h3>Two-factor authentication</h3><p class="muted-copy">Add an authenticator code to protect your account.</p><div id="twofactor-area"><span class="muted-copy">Loading…</span></div></div><div class="profile-section"><h3>API tokens</h3><p class="muted-copy">Tokens are shown once when created. Use them as a Bearer token and revoke any token you no longer need.</p><div id="api-token-area"><span class="muted-copy">Loading…</span></div></div><div class="profile-section"><h3>Change password</h3><form id="change-password-form" class="user-manage"><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New password<input name="new_password" type="password" minlength="12" autocomplete="new-password" required><small>Use at least 12 characters. You will need to sign in again.</small></label><div id="password-error" class="form-error" role="alert"></div><button class="button subtle" type="submit">Change password</button></form></div><div class="modal-actions"><button class="button danger" id="sign-out">Sign out</button></div>`);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);const area=document.querySelector('#twofactor-area');api('/api/2fa/status').then(x=>{area.innerHTML=x.enabled?'<form id="disable-2fa-form" class="user-manage"><span class="status-badge good"><i></i> Enabled</span><label>Account password<input name="password" type="password" autocomplete="current-password" required></label><label>Authenticator code<input name="code" inputmode="numeric" pattern="[0-9]{6}" required></label><button class="button subtle" type="submit">Disable authenticator</button></form>':'<button class="button subtle" id="start-2fa">Set up authenticator</button>';document.querySelector('#start-2fa')?.addEventListener('click',setup2FA);}).catch(e=>area.textContent=e.message);loadAPITokens();document.querySelector('#sign-out').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});closeModal();renderLogin()};}
  async function loadAPITokens(){const area=document.querySelector('#api-token-area');if(!area)return;try{const tokens=await api('/api/tokens');area.innerHTML=`<div class="grant-list">${tokens.map(t=>`<div class="grant-row"><div><b>${esc(t.name)}</b><button class="button link" data-revoke-token="${esc(t.id)}">Revoke</button></div><small>${esc((t.scopes||[]).join(', '))} · created ${esc(t.created_at)}${t.last_used_at?` · used ${esc(t.last_used_at)}`:''}</small></div>`).join('')||'<div class="files-empty">No API tokens yet.</div>'}</div><form id="new-api-token" class="user-manage" style="margin-top:12px"><label>Token name<input name="name" maxlength="80" required placeholder="Deploy script"></label><div class="grant-heading"><h3>Scopes</h3><span>Always limited by your account grants</span></div><div class="grant-checks">${['server.view','server.control','server.console','server.files','server.backup','server.schedule','server.create','server.delete',...(state.user.role==='admin'?['admin']:[])].map(p=>`<label><input type="checkbox" name="scope" value="${p}"><span>${p}</span></label>`).join('')}</div><button class="button subtle" type="submit">Create API token</button></form>`;area.querySelectorAll('[data-revoke-token]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this API token?'))return;try{await api(`/api/tokens/${b.dataset.revokeToken}`,{method:'DELETE'});toast('API token revoked','success');loadAPITokens()}catch(e){toast(e.message,'error')}});area.querySelector('#new-api-token').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{const created=await api('/api/tokens',{method:'POST',body:JSON.stringify({name:form.get('name'),scopes:form.getAll('scope')})});await loadAPITokens();const current=document.querySelector('#api-token-area');if(current){const reveal=document.createElement('div');reveal.className='totp-secret';reveal.innerHTML=`<small>Copy this token now. It will not be shown again.</small><code>${esc(created.token)}</code><button class="button subtle" type="button" id="copy-api-token">Copy token</button>`;current.prepend(reveal);current.querySelector('#copy-api-token').onclick=()=>navigator.clipboard.writeText(created.token).then(()=>toast('API token copied','success'));}toast('API token created','success')}catch(err){toast(err.message,'error')}};}catch(e){area.textContent=e.message}}
  async function setup2FA(){try{const x=await api('/api/2fa/setup',{method:'POST',body:'{}'});const area=document.querySelector('#twofactor-area');area.innerHTML=`<div class="totp-secret"><small>Enter this key in your authenticator app:</small><code>${esc(x.secret)}</code><small>Provisioning URI</small><code class="uri-code">${esc(x.otpauth_url)}</code></div><form id="verify-2fa"><label>Six-digit code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></label><button class="button primary">Verify & enable</button></form>`;document.querySelector('#verify-2fa').onsubmit=async e=>{e.preventDefault();try{await api('/api/2fa/enable',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Two-factor authentication enabled','success');showProfile()}catch(err){toast(err.message,'error')}};}catch(e){toast(e.message,'error')}}
  function modal(content){closeModal();const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<div class="modal-backdrop" data-backdrop></div><section class="modal-card" role="dialog" aria-modal="true">${content}</section>`;document.body.append(layer);layer.querySelector('[data-backdrop]').addEventListener('click',closeModal);const first=layer.querySelector('input,select,textarea,button');first?.focus();}
  function closeModal(){document.querySelector('.modal-layer')?.remove();}

  if(localStorage.getItem('ygg-theme')==='light')document.documentElement.classList.add('light');
  document.addEventListener('submit',async e=>{if(e.target.id==='disable-2fa-form'){e.preventDefault();try{await api('/api/2fa/disable',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();state.user=null;renderLogin();toast('Authenticator disabled. Sign in again.','success')}catch(err){toast(err.message,'error')}return;}if(e.target.id!=='change-password-form')return;e.preventDefault();const error=document.querySelector('#password-error');error.textContent='';try{await api('/api/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();state.user=null;renderLogin();toast('Password changed. Sign in with the new password.','success')}catch(err){error.textContent=err.message}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  setInterval(async()=>{if(state.user&&!document.querySelector('.modal-layer')){try{await refresh();if(!state.selected&&state.route==='servers')renderServers();}catch{}}},15000);
  boot();
})();
